function validate([grid]) {
  const n = grid.length;
  if (n < 3 || n > 100) return 'grid needs 3 to 100 rows.';
  if (grid.some(row => row.length !== n)) return 'grid must be square (n rows of n values).';
  if (grid.some(row => row.some(v => !Number.isInteger(v) || v < 0 || v > 100000))) return 'Each value is between 0 and 10^5.';
  return null;
}

