function checkXMatrix(grid) {
  const n = grid.length;
  const diagonal = new Set();
  for (let k = 0; k < n; k++) {
    diagonal.add(k * n + k);
    diagonal.add(k * n + (n - 1 - k));
  }
  let nonZero = 0;
  grid.forEach(row => row.forEach(v => { if (v !== 0) nonZero++; }));
  const diagonalFilled = [...diagonal].every(cell => grid[Math.floor(cell / n)][cell % n] !== 0);
  return diagonalFilled && nonZero === diagonal.size;
}

