function generate(rand, size) {
  const n = size === 'large' ? 80 + Math.floor(rand() * 21) : 3 + Math.floor(rand() * 4);
  const top = rand() < 0.5 ? 9 : 100000;
  const value = () => 1 + Math.floor(rand() * top);
  const grid = Array.from({ length: n }, (_, i) => Array.from({ length: n }, (_, j) => (i === j || i + j === n - 1) ? value() : 0));
  if (rand() < 0.5) return [grid];
  const flips = 1 + Math.floor(rand() * 2);
  for (let f = 0; f < flips; f++) {
    const i = Math.floor(rand() * n);
    const j = Math.floor(rand() * n);
    grid[i][j] = grid[i][j] === 0 ? value() : 0;
  }
  return [grid];
}
